// Source of truth: logic/dedupe.js (unit tested in tests/dedupe.test.js).
const FREE_EMAIL_DOMAINS = ['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','aol.com','icloud.com','proton.me','protonmail.com','gmx.com','mail.com'];
function normalizeEmail(email) {
  if (typeof email !== 'string' || !email.includes('@')) return '';
  const e = email.trim().toLowerCase();
  let local = e.slice(0, e.lastIndexOf('@'));
  let domain = e.slice(e.lastIndexOf('@') + 1);
  const plus = local.indexOf('+');
  if (plus > 0) local = local.slice(0, plus);
  if (domain === 'gmail.com' || domain === 'googlemail.com') { local = local.split('.').join(''); domain = 'gmail.com'; }
  return local && domain ? local + '@' + domain : '';
}
function normalizePhone(p) {
  const d = String(p || '').replace(/[^0-9]/g, '');
  return d.length < 7 ? '' : d.slice(-10);
}
function normalizeDomain(v) {
  let d = String(v || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '');
  d = d.split('/')[0].split('?')[0].split(':')[0];
  return d.includes('.') ? d : '';
}
function normalizeName(n) {
  return String(n || '').trim().toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}
return $input.all().map((item) => {
  const r = item.json;
  const emailKey = normalizeEmail(r.email);
  const emailDomain = emailKey.split('@').pop();
  const domainKey = normalizeDomain(r.domain) || (emailDomain && !FREE_EMAIL_DOMAINS.includes(emailDomain) ? emailDomain : '');
  return { json: Object.assign({}, r, {
    email_key: emailKey, phone_key: normalizePhone(r.phone),
    domain_key: domainKey, name_key: normalizeName(r.name)
  }) };
});

// Source of truth: logic/dedupe.js. Merge only on a strong identifier.
// Name similarity alone never reaches the merge threshold - merging two real
// people is unrecoverable, a missed merge is not.
const MATCH_THRESHOLDS = { merge: 0.9, review: 0.6 };
function levenshtein(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = [];
  for (let j = 0; j <= b.length; j++) prev[j] = j;
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      const cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[b.length];
}
function nameSim(a, b) {
  if (!a || !b) return 0;
  if (a === b) return 1;
  return 1 - levenshtein(a, b) / Math.max(a.length, b.length);
}
const rows = $input.all().map((i) => i.json);
const pairs = [];
for (let i = 0; i < rows.length; i++) {
  for (let j = i + 1; j < rows.length; j++) {
    const a = rows[i]; const b = rows[j];
    let score = 0; const evidence = [];
    if (a.email_key && a.email_key === b.email_key) { score = Math.max(score, 1); evidence.push('email_exact'); }
    if (a.phone_key && a.phone_key === b.phone_key) { score = Math.max(score, 0.95); evidence.push('phone_exact'); }
    const sim = nameSim(a.name_key, b.name_key);
    if (a.domain_key && a.domain_key === b.domain_key) {
      evidence.push('domain_exact');
      if (sim >= 0.85) { score = Math.max(score, 0.9); evidence.push('name_similar'); }
      else { score = Math.max(score, 0.45); }
    } else if (sim >= 0.92) { score = Math.max(score, 0.6); evidence.push('name_only'); }
    if (score < MATCH_THRESHOLDS.review) continue;
    const decision = score >= MATCH_THRESHOLDS.merge ? 'merge' : 'review';
    const [keep, drop] = new Date(a.created_at) <= new Date(b.created_at) ? [a, b] : [b, a];
    pairs.push({ json: { decision, score: Number(score.toFixed(3)), evidence,
      keep_id: keep.id, drop_id: drop.id, keep_email: keep.email, drop_email: drop.email } });
  }
}
return pairs.length ? pairs : [{ json: { decision: 'none', score: 0, evidence: [], keep_id: null, drop_id: null } }];

